head.script:
// 테스트 설명, 유효성 값 설정
//  - "Header/Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성)
//    본 샘플(_2)은 병합된 Header Column 에 설정, column_P_fixColumnWidth_1 은 Body Column 에 설정
//  - 본 샘플(_2) : setColumnWidth() / 병합된 Header Column / RowNum, RowStatus Column 축
//    true/false/미설정 동작, 마우스 포인터, autoFit(allColumn, lastColumn), resize 항목은 column_P_fixColumnWidth_1 소유
scwin.tData = {
    "description" : "[column > P > fixColumnWidth]<br/>Column 의 너비(Width)를 고정할지 설정합니다.",
    "validation" : [
        "setColumnWidth() 메소드를 사용하면 fixColumnWidth 속성값에 관계없이 Column 의 너비를 변경할 수 있습니다.",
        "병합된 Header Column 에 설정하면 병합된 Column 중 첫번째 Column 에만 적용됩니다.",
        "RowNum, RowStatus Column 은 fixColumnWidth 속성이 동작하지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean : 1=미설정 / 2=true / 3=false)
    con_fixColumnWidth.setValue("2");
    con_autoFit.setValue("");
    par_columnInfo.setValue("code");
    par_size.setValue("200");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - fixColumnWidth(con 값) 는 병합된 Header Column(product : code, name 2개 Column 병합) 에만 설정
//  - RowNum, RowStatus Column 표시, rowNumStatusResize="true" 고정 (RowNum, RowStatus Column 도 마우스 Drag 대상)
//  - 각 Column 너비 100px, GridView 너비 700px
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cFixColumnWidth = con_fixColumnWidth.getText();
    let cAutoFit = con_autoFit.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] fixColumnWidth 는 병합된 Header Column(product = code + name) 에만 설정, RowNum/RowStatus Column 표시, rowNumStatusResize=true, 각 Column 너비 100px\n[절차] RowNum, RowStatus, code, name Header Column 오른쪽 경계에 마우스 오버하여 포인터 확인 -> Drag 로 너비 변경\n[확인] Column 너비 확인 버튼으로 각 Column 너비 확인, setColumnWidth 실행 후 너비 확인"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "code" : "P-1001", "name" : "무선 키보드", "qty" : 12, "memo" : "입고 대기" },
        { "code" : "P-1002", "name" : "광마우스", "qty" : 30, "memo" : "정상" },
        { "code" : "P-1003", "name" : "모니터 받침대", "qty" : 7, "memo" : "재고 부족" }
    ], false);

    // GridView 속성
    let attrGrid = ' rowNumVisible="true" rowStatusVisible="true" rowNumStatusResize="true"';
    attrGrid += (cAutoFit === '') ? '' : ' autoFit="' + cAutoFit + '"';

    // 검증 대상 병합 Header Column 속성
    let attrFix = (cFixColumnWidth === '') ? '' : ' fixColumnWidth="' + cFixColumnWidth + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:700px;height:150px;"' + attrGrid + '>';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="product" colSpan="2"' + attrFix + '></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="qty" rowSpan="2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="memo" rowSpan="2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="code"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column5" value="name"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="code" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="qty" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="memo" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 각 Column 의 화면 너비(Header Column 기준, px) 문자열
scwin.getColumnWidthText = function () {
    let arrHeader = ["_headerRowNumber", "_headerRowStatus", "column4", "column5", "column2", "column3"];
    let arrName = ["RowNum", "RowStatus", "code", "name", "qty", "memo"];
    let arr = [];
    for (let i = 0; i < arrHeader.length; i++) {
        let th = document.querySelector("[id='" + target1.id + "_" + arrHeader[i] + "']");
        arr.push(arrName[i] + " : " + (th ? th.offsetWidth : "-"));
    }
    return arr.join(" / ");
}



// validation 2, 3 판정 출력 : 마우스 Drag 후 각 Column 너비
scwin.btn_checkColumnWidth_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("Column 너비 : " + scwin.getColumnWidthText());
}



// validation 1 판정 출력 : setColumnWidth(columnInfo, size) 실행 후 각 Column 너비
scwin.btn_setColumnWidth_onclick = function () {
    let columnInfo = par_columnInfo.getValue();
    let size = Number(par_size.getValue());
    target1.setColumnWidth(columnInfo, size);
    wf_body_bottom.getObj("scwin").setReturnValue("setColumnWidth(" + columnInfo + ", " + size + ") -> Column 너비 : " + scwin.getColumnWidthText());
}
